import requests

# Contract: GET /v1/orders/{id} -> 200 + Order | 404 + Problem | 429 + Retry-After
resp = requests.get(
    "/v1/orders/42",
    headers={
        "Authorization": "Bearer <token>",
        "Accept": "application/json",
    },
    timeout=(2, 5),  # connect, read: timeouts are part of using the contract
)

if resp.status_code == 200:
    order = resp.json()  # validated against Order schema
elif resp.status_code == 404:
    order = None  # normal control flow, not an exception
elif resp.status_code == 429:
    # Contract says: honor Retry-After, back off. Do not spin.
    raise RuntimeError(f"throttled, retry after {resp.headers.get('Retry-After')}")
else:
    resp.raise_for_status()

